import React, { useState, useEffect } from 'react';
import { 
    Box, 
    Button, 
    useTheme,
    Typography,
    alpha
} from '@mui/material';
import { DateRange as DateIcon } from '@mui/icons-material';
import BaseModal from '../BaseModal';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import dayjs from 'dayjs';

const DateRangeModal = ({ 
    open, 
    onClose, 
    onApply, 
    initialRange = null,
    loading = false,
    title = "Filter export by date added",
    description = "Only records whose created or added date falls within this range will be included in the export.",
}) => {
    const theme = useTheme();

    const [range, setRange] = useState({
        startDate: null,
        endDate: null
    });

    useEffect(() => {
        if (open) {
            if (initialRange) {
                setRange({
                    startDate: initialRange.startDate ? dayjs(initialRange.startDate) : null,
                    endDate: initialRange.endDate ? dayjs(initialRange.endDate) : null
                });
            } else {
                setRange({
                    startDate: null,
                    endDate: null
                });
            }
        }
    }, [open, initialRange]);

    const handleApply = () => {
        if (onApply) {
            onApply({
                startDate: range.startDate,
                endDate: range.endDate
            });
        }
    };

    const isInvalid = !range.startDate || !range.endDate || range.startDate.isAfter(range.endDate);

    const datePickerSx = {
        '& .MuiOutlinedInput-root': {
            backgroundColor: '#111111',
            borderRadius: '10px',
            height: '48px',
            '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.12)' },
            '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.25)' },
            '&.Mui-focused fieldset': { 
                borderColor: '#4CC66E',
                borderWidth: '1.5px'
            },
            '& .MuiInputAdornment-root .MuiSvgIcon-root': {
                color: '#4CC66E',
            }
        },
        '& .MuiInputBase-input': {
            color: '#FFFFFF',
            fontSize: '0.875rem',
        }
    };

    const popperSx = {
        sx: {
            backgroundColor: '#1A1A1A',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            borderRadius: '12px',
            boxShadow: '0 8px 32px rgba(0, 0, 0, 0.6)',
            '& .MuiTypography-root': { color: '#FFFFFF' },
            '& .MuiPickersDay-root': { 
                color: '#AAAAAA',
                '&:hover': { backgroundColor: alpha('#4CC66E', 0.1) },
                '&.Mui-selected': { 
                    backgroundColor: '#4CC66E',
                    color: '#000000',
                    '&:hover': { backgroundColor: '#3DA15A' }
                }
            },
            '& .MuiTabs-root': {
                backgroundColor: '#1A1A1A',
                '& .MuiTab-root': { color: '#AAAAAA' },
                '& .Mui-selected': { color: '#4CC66E' }
            }
        }
    };

    const actions = (
        <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', flexDirection: { xs: 'column', sm: 'row' } }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleApply}
                disabled={loading || isInvalid}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(255, 255, 255, 0.5)'
                    }
                }}
            >
                {loading ? 'Exporting...' : 'Export'}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={title}
            maxWidth="xs"
            actions={actions}
        >
            <Box 
                sx={{ 
                    pt: 2,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 3,
                    width: '100%',
                }}
            >
                <Typography
                    variant="body2"
                    sx={{
                        color: 'rgba(255, 255, 255, 0.65)',
                        lineHeight: 1.6,
                        fontSize: '0.875rem',
                    }}
                >
                    {description}
                </Typography>

                <LocalizationProvider dateAdapter={AdapterDayjs}>
                    <Box sx={{ display: 'flex', gap: 2, flexDirection: 'column'}}>
                        <Box sx={{ flex: 1 }}>
                            <Typography 
                                variant="caption" 
                                sx={{ 
                                    color: 'text.secondary', 
                                    fontWeight: 700, 
                                    mb: 1, 
                                    display: 'flex', 
                                    alignItems: 'center',
                                    gap: 1,
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.05em'
                                }}
                            >
                                <DateIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                Start Date
                            </Typography>
                            <DatePicker
                                value={range.startDate}
                                onChange={(val) => setRange(prev => ({ ...prev, startDate: val }))}
                                format="YYYY-MM-DD"
                                slotProps={{
                                    textField: {
                                        fullWidth: true,
                                        placeholder: 'Select start date',
                                        sx: datePickerSx
                                    },
                                    desktopPaper: popperSx,
                                    mobilePaper: popperSx,
                                    popper: { placement: 'bottom-start' }
                                }}
                            />
                        </Box>

                        <Box sx={{ flex: 1 }}>
                            <Typography 
                                variant="caption" 
                                sx={{ 
                                    color: 'text.secondary', 
                                    fontWeight: 700, 
                                    mb: 1, 
                                    display: 'flex', 
                                    alignItems: 'center',
                                    gap: 1,
                                    textTransform: 'uppercase',
                                    letterSpacing: '0.05em'
                                }}
                            >
                                <DateIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                                End Date
                            </Typography>
                            <DatePicker
                                value={range.endDate}
                                onChange={(val) => setRange(prev => ({ ...prev, endDate: val }))}
                                format="YYYY-MM-DD"
                                minDate={range.startDate}
                                slotProps={{
                                    textField: {
                                        fullWidth: true,
                                        placeholder: 'Select end date',
                                        sx: datePickerSx
                                    },
                                    desktopPaper: popperSx,
                                    mobilePaper: popperSx,
                                    popper: { placement: 'bottom-start' }
                                }}
                            />
                        </Box>
                    </Box>
                </LocalizationProvider>
                
                {range.startDate && range.endDate && range.startDate.isAfter(range.endDate) && (
                    <Typography color="error" variant="caption" sx={{ mt: -2 }}>
                        Start date cannot be after end date.
                    </Typography>
                )}
            </Box>
        </BaseModal>
    );
};

export default DateRangeModal;
