import React, { useMemo, useState, useEffect, useCallback, memo } from "react";
import { useDebounce } from "../hooks/useDebounce";
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Box,
  CircularProgress,
  TablePagination,
  useTheme,
  alpha,
  Typography,
  TextField,
  InputAdornment,
  Button,
  TableSortLabel,
  IconButton,
  Tooltip,
  Menu,
  MenuItem,
} from "@mui/material";
import {
  Search as SearchIcon,
  FileDownloadOutlined as ExportIcon,
  Add as AddIcon,
  VisibilityOutlined as ViewIcon,
  EditOutlined as EditIcon,
  DeleteOutline as DeleteIcon,
  CalendarMonth as DateIcon,
  FilterList as FilterIcon,
  Notifications as NotificationIcon,
  LockOutlined as ResetPasswordIcon,
} from "@mui/icons-material";
import EmptyData from "./EmptyData";
import DateRangeModal from "./page_components/DateRangeModal";


const SafeCell = memo(({ column, row }) => {
  try {
    if (typeof column.render === "function") {
      return column.render(row) ?? null;
    }
    const val = row?.[column.id];
    return val !== undefined && val !== null ? String(val) : "-";
  } catch (err) {
    console.warn(`[DataTable] Error rendering column "${column.id}":`, err);
    return <span style={{ color: "#FF5050", fontSize: "0.75rem" }}>-</span>;
  }
});

// ─── Helpers ──────────────────────────────────────────────────────────────────
const toArray = (val) => (Array.isArray(val) ? val : []);
const toNum = (val, fallback = 0) =>
  Number.isFinite(Number(val)) ? Number(val) : fallback;
const toFn = (val) => (typeof val === "function" ? val : () => {});

const DataTable = ({
  title = "",
  columns,
  data,
  isLoading = false,
  pagination,
  searchTerm = "",
  onSearchChange,
  orderBy = "",
  order = "asc",
  onSortChange,
  onExportClick,
  onAddClick,
  addLabel = "Add",
  /** Primary toolbar button icon. Omit for default + icon; pass `null` for text-only. */
  addStartIcon,
  onViewClick,
  onEditClick,
  onDeleteClick,
  emptyTitle,
  emptyMessage,
  onRetry,
  onDateRangeClick,
  hasActiveDateFilter,
  dateFilterTooltip = "Filter by date range",
  onFilterClick,
  hasActiveFilters,
  filters,
  onRowClick,
  onNotificationClick,
  onResetPasswordClick,
  onExport, // New prop for centralized export
  isExporting = false, // Loading state for export
  getRowSx, // Added for custom row styling
}) => {
  const theme = useTheme();

  // ── Export UI State ───────────────────────────────────────────────────────────
  const [exportAnchorEl, setExportAnchorEl] = useState(null);
  const [isDateModalOpen, setIsDateModalOpen] = useState(false);
  const [exportFormat, setExportFormat] = useState("csv");

  const handleExportButtonClick = (event) => {
    if (onExport) {
      setExportAnchorEl(event.currentTarget);
    } else if (onExportClick) {
      onExportClick(event);
    }
  };

  const handleCloseExportMenu = () => {
    setExportAnchorEl(null);
  };

  const handleSelectExportFormat = (format) => {
    setExportFormat(format);
    handleCloseExportMenu();
    setIsDateModalOpen(true);
  };

  const handleApplyDateRange = (dates) => {
    setIsDateModalOpen(false);
    if (onExport) {
      onExport(dates, exportFormat);
    }
  };

  // ── Normalise every external prop so the rest of the component is clean ──
  const safeData = toArray(data);
  const safeColumns = toArray(columns);

  const safePagination = {
    page: toNum(pagination?.page, 0),
    rowsPerPage: toNum(pagination?.rowsPerPage, 5),
    totalCount: toNum(pagination?.totalCount, 0),
    onPageChange: toFn(pagination?.onPageChange),
    onRowsPerPageChange: toFn(pagination?.onRowsPerPageChange),
  };

  // ── Debounced search ──────────────────────────────────────────────────────
  const [inputValue, setInputValue] = useState(String(searchTerm ?? ""));

  useEffect(() => {
    setInputValue(String(searchTerm ?? ""));
  }, [searchTerm]);

  const fireSearch = useCallback(
    (value) => {
      onSearchChange?.(value);
    },
    [onSearchChange],
  );
  const debouncedSearch = useDebounce(fireSearch, 1000);

  const handleInputChange = (e) => {
    const value = e.target.value;
    setInputValue(value);
    debouncedSearch(value);
  };
  // ─────────────────────────────────────────────────────────────────────────

  const createSortHandler = (property) => () => {
    onSortChange?.(property);
  };

  const hasActions = onViewClick || onEditClick || onDeleteClick || onNotificationClick || onResetPasswordClick;

  const finalColumns = useMemo(() => {
    if (!hasActions) return safeColumns;
    if (safeColumns.find((c) => c.id === "actions")) return safeColumns;

    return [
      ...safeColumns,
      {
        id: "actions",
        label: "Actions",
        sortable: false,
        align: "center",
        render: (row) => (
          <Box sx={{ display: "flex", justifyContent: "center", gap: 0.5 }}>
            {onViewClick && (
              <Tooltip title="View Details">
                <IconButton
                  size="small"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (typeof onViewClick === "function") onViewClick(row);
                  }}
                  sx={{
                    color: "#9F6EDA",
                    "&:hover": {
                      color: "#9F6EDA",
                      bgcolor: alpha("#9F6EDA", 0.08),
                    },
                  }}
                >
                  <ViewIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
            {onEditClick && (
              <Tooltip title="Edit">
                <IconButton
                  size="small"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (typeof onEditClick === "function") onEditClick(row);
                  }}
                  sx={{
                    color: "#9F6EDA",
                    "&:hover": {
                      color: "#9F6EDA",
                      bgcolor: alpha("#9F6EDA", 0.08),
                    },
                  }}
                >
                  <EditIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
            {onNotificationClick && (
              <Tooltip title="Send Notification">
                <IconButton
                  size="small"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (typeof onNotificationClick === "function") onNotificationClick(row);
                  }}
                  sx={{
                    color: "#9F6EDA",
                    "&:hover": {
                      color: "#9F6EDA",
                      bgcolor: alpha("#9F6EDA", 0.08),
                    },
                  }}
                >
                  <NotificationIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
            {onResetPasswordClick && (
              <Tooltip title="Change Password">
                <IconButton
                  size="small"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (typeof onResetPasswordClick === "function") onResetPasswordClick(row);
                  }}
                  sx={{
                    color: "#F5A623",
                    "&:hover": {
                      color: "#F5A623",
                      bgcolor: alpha("#F5A623", 0.08),
                    },
                  }}
                >
                  <ResetPasswordIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
            {onDeleteClick && (
              <Tooltip title="Delete">
                <IconButton
                  size="small"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (typeof onDeleteClick === "function") onDeleteClick(row);
                  }}
                  sx={{
                    color: "error.main",
                    "&:hover": {
                      color: "error.main",
                      bgcolor: alpha(theme.palette.error.main, 0.08),
                    },
                  }}
                >
                  <DeleteIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            )}
          </Box>
        ),
      },
    ];
  }, [
    safeColumns,
    hasActions,
    onViewClick,
    onEditClick,
    onDeleteClick,
    onNotificationClick,
    onResetPasswordClick,
    theme.palette,
  ]);

  return (
    <Paper
      elevation={0}
      sx={{
        width: "100%",
        borderRadius: "24px",
        border: "1px solid rgba(255, 255, 255, 0.08)",
        overflow: "hidden",
        background: "#001e08ff",
        backdropFilter: "blur(12px)",
        fontFamily: "'Montserrat', sans-serif",
      }}
    >
      {/* ── Toolbar ─────────────────────────────────────────────────────── */}
      <Box
        sx={{
          px: { xs: 2, md: 2.5 },
          py: { xs: 1.5, md: 2 },
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "space-between",
          alignItems: "center",
          gap: 1.5,
          borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
        }}
      >
        {/* Title */}
        <Typography
          sx={{
            fontWeight: 700,
            color: "#FFFFFF",
            fontFamily: "'Montserrat', sans-serif",
            fontSize: { xs: "1.5rem", md: "1.8rem" },
            whiteSpace: "nowrap",
          }}
        >
          {title}
          {(safePagination.totalCount > 0 || safeData.length > 0) && (
            <Typography
              component="span"
              sx={{
                color: "#9F6EDA",
                ml: 1,
                fontWeight: 400,
                fontFamily: "'Montserrat', sans-serif",
                fontSize: "1.2rem",
              }}
            >
              ({safePagination.totalCount || safeData.length})
            </Typography>
          )}
        </Typography>

        {/* Controls */}
        <Box
          sx={{
            display: "flex",
            alignItems: "center",
            gap: 1,
            flexWrap: "wrap",
            justifyContent: "flex-end",
            flex: "1 1 auto",
          }}
        >
          {/* Search */}
          {typeof onSearchChange === "function" && (
            <TextField
              size="small"
              placeholder="Search..."
              value={inputValue}
              onChange={handleInputChange}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon sx={{ color: "#8B8D97", fontSize: "1rem" }} />
                  </InputAdornment>
                ),
              }}
              sx={{
                width: { xs: "100%", sm: 250 },
                maxWidth: { xs: "none", sm: 250 },
                margin: 0,
                "& .MuiOutlinedInput-root": {
                  height: "36px",
                  bgcolor: "rgba(255, 255, 255, 0.05)",
                  borderRadius: "12px",
                  color: "#FFFFFF",
                  fontSize: "0.8rem",
                  fontFamily: "'Montserrat', sans-serif",
                  boxSizing: "border-box",
                  "& fieldset": {
                    borderColor: "rgba(255, 255, 255, 0.08)",
                    top: 0,
                  },
                  "& fieldset legend": { display: "none" },
                  "&:hover fieldset": {
                    borderColor: "rgba(255, 255, 255, 0.15)",
                  },
                  "&.Mui-focused fieldset": {
                    borderColor: "#4CC66E",
                    borderWidth: "1px",
                    boxShadow: "0 0 10px rgba(76, 198, 110, 0.2)",
                  },
                },
                "& .MuiInputBase-input": {
                  padding: 0,
                  height: "100%",
                  boxSizing: "border-box",
                  "&::placeholder": { color: "#8B8D97", opacity: 1 },
                },
              }}
            />
          )}

          {filters && <Box sx={{ display: "flex", gap: 1 }}>{filters}</Box>}

          {/* Date Range */}
          {typeof onDateRangeClick === "function" && (
            <Tooltip title={dateFilterTooltip}>
              <Button
                variant={hasActiveDateFilter ? "contained" : "outlined"}
                startIcon={<DateIcon sx={{ fontSize: "0.9rem !important" }} />}
                onClick={onDateRangeClick}
                size="small"
                sx={{
                  width: { xs: "100%", sm: "auto" },
                  height: 36,
                  px: 1.5,
                  fontWeight: 600,
                  fontSize: "0.75rem",
                  borderRadius: "8px",
                  textTransform: "none",
                  fontFamily: "'Montserrat', sans-serif",
                  whiteSpace: "nowrap",
                  borderColor: hasActiveDateFilter
                    ? "#4CC66E"
                    : "rgba(255, 255, 255, 0.12)",
                  bgcolor: hasActiveDateFilter
                    ? "#4CC66E"
                    : "rgba(255, 255, 255, 0.03)",
                  color: hasActiveDateFilter
                    ? "#000000"
                    : "rgba(255, 255, 255, 0.8)",
                  "&:hover": {
                    bgcolor: hasActiveDateFilter
                      ? "#3EB05D"
                      : "rgba(76, 198, 110, 0.08)",
                    borderColor: "#4CC66E",
                    color: hasActiveDateFilter ? "#000000" : "#4CC66E",
                  },
                }}
              >
                {hasActiveDateFilter ? "Date: Active" : "Date Range"}
              </Button>
            </Tooltip>
          )}

          {/* Filters */}
          {typeof onFilterClick === "function" && (
            <Button
              variant={hasActiveFilters ? "contained" : "outlined"}
              startIcon={<FilterIcon sx={{ fontSize: "0.9rem !important" }} />}
              onClick={onFilterClick}
              size="small"
              sx={{
                width: { xs: "100%", sm: "auto" },
                height: 36,
                px: 1.5,
                fontWeight: 600,
                fontSize: "0.75rem",
                borderRadius: "8px",
                textTransform: "none",
                fontFamily: "'Montserrat', sans-serif",
                borderColor: hasActiveFilters
                  ? "#4CC66E"
                  : "rgba(255, 255, 255, 0.12)",
                bgcolor: hasActiveFilters
                  ? "#4CC66E"
                  : "rgba(255, 255, 255, 0.03)",
                color: hasActiveFilters
                  ? "#000000"
                  : "rgba(255, 255, 255, 0.8)",
                "&:hover": {
                  bgcolor: hasActiveFilters
                    ? "#3EB05D"
                    : "rgba(76, 198, 110, 0.08)",
                  borderColor: "#4CC66E",
                  color: hasActiveFilters ? "#000000" : "#4CC66E",
                },
              }}
            >
              Filters
            </Button>
          )}

          {/* Export */}
          {(typeof onExportClick === "function" || typeof onExport === "function") && (
            <Button
              variant="outlined"
              startIcon={<ExportIcon sx={{ fontSize: "0.9rem !important" }} />}
              onClick={handleExportButtonClick}
              size="small"
              sx={{
                width: { xs: "100%", sm: "auto" },
                height: 36,
                px: 1.5,
                fontWeight: 600,
                fontSize: "0.75rem",
                borderRadius: "8px",
                textTransform: "none",
                fontFamily: "'Montserrat', sans-serif",
                borderColor: "#9F6EDA",
                color: "#000",
                bgcolor: "#9F6EDA",
                "&:hover": {
                  borderColor: "#9F6EDA",
                  color: "#9F6EDA",
                  bgcolor: "rgba(159, 110, 218, 0.15)",
                },
              }}
            >
              Export
            </Button>
          )}

          {/* Add */}
          {typeof onAddClick === "function" && (
            <Button
              variant="contained"
              {...(addStartIcon === null
                ? {}
                : {
                    startIcon:
                      addStartIcon !== undefined ? (
                        addStartIcon
                      ) : (
                        <AddIcon sx={{ fontSize: "0.9rem !important" }} />
                      ),
                  })}
              onClick={onAddClick}
              size="small"
              sx={{
                width: { xs: "100%", sm: "auto" },
                height: 36,
                px: 1.5,
                fontWeight: 700,
                fontSize: "0.75rem",
                borderRadius: "8px",
                textTransform: "none",
                fontFamily: "'Montserrat', sans-serif",
                bgcolor: "#9F6EDA",
                color: "#000000",
                boxShadow: "0 4px 16px rgba(76, 198, 110, 0.2)",
                transition: "all 0.2s ease",
                "&:hover": {
                  bgcolor: "#9F6EDA",
                
                  transform: "translateY(-1px)",
                },
              }}
            >
              {addLabel}
            </Button>
          )}
        </Box>
      </Box>

      {/* ── Table Container ─────────────────────────────────────────────── */}
      <TableContainer
        sx={{
          position: "relative",
          minHeight: safeData.length === 0 ? 300 : "auto",
          bgcolor: "#001e08ff",
          overflowX: "auto",
        }}
      >
        {/* Loading overlay */}
        {isLoading && (
          <Box
            sx={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: "#001e08ff", // Use same opaque background as table
              zIndex: 2,
            }}
          >
            <CircularProgress size={40} />
          </Box>
        )}

        {/* Empty state */}
        {safeData.length === 0 && !isLoading ? (
          <Box sx={{ py: 8, bgcolor: "#001e08ff" }}>
            <EmptyData
              title={emptyTitle || "No items found"}
              description={
                emptyMessage ||
                "Try adjusting your search or filters to find what you're looking for."
              }
            />
          </Box>
        ) : (
          <Table stickyHeader>
            <TableHead>
              <TableRow>
                {finalColumns.map((column, colIdx) => (
                  <TableCell
                    key={column.id ?? colIdx}
                    align={column.align || "left"}
                    sortDirection={orderBy === column.id ? order : false}
                    sx={{
                      whiteSpace: "nowrap",
                      bgcolor: "rgba(255, 255, 255, 0.02)",
                      color: "rgba(255, 255, 255, 0.5)",
                      fontWeight: 700,
                      fontSize: "0.75rem",
                      textTransform: "uppercase",
                      letterSpacing: "0.05em",
                      py: 2,
                      borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
                      fontFamily: "'Montserrat', sans-serif",
                    }}
                  >
                    {column.sortable === false || !column.sortable ? (
                      column.label
                    ) : (
                      <TableSortLabel
                        active={orderBy === column.id}
                        direction={orderBy === column.id ? order : "asc"}
                        onClick={createSortHandler(column.id)}
                        sx={{
                          color: "#8B8D97 !important",
                          "&.Mui-active": { color: "#4CC66E !important" },
                          "& .MuiTableSortLabel-icon": {
                            color: "#4CC66E !important",
                          },
                        }}
                      >
                        {column.label}
                      </TableSortLabel>
                    )}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {safeData.map((row, rowIdx) => (
                <TableRow
                  hover
                  key={row?.id ?? rowIdx}
                  sx={{
                    "&:last-child td, &:last-child th": { border: 0 },
                    cursor:
                      typeof onRowClick === "function" ? "pointer" : "default",
                    "&:hover": {
                      bgcolor: "rgba(76, 198, 110, 0.06) !important",
                    },
                    ...(typeof getRowSx === "function" ? getRowSx(row) : {}),
                  }}
                  onClick={(e) => {
                    const tag = e.target?.tagName?.toLowerCase();
                    if (
                      tag === "button" ||
                      tag === "a" ||
                      tag === "input" ||
                      e.target?.closest?.(".MuiChip-root, .MuiIconButton-root, .MuiButtonBase-root")
                    ) {
                      return;
                    }
                    if (typeof onRowClick === "function") onRowClick(row);
                  }}
                >
                  {finalColumns.map((column, colIdx) => (
                    <TableCell
                      key={column.id ?? colIdx}
                      align={column.align || "left"}
                      sx={{
                        py: 2.5,
                        fontSize: "0.875rem",
                        color: "rgba(255, 255, 255, 0.9)",
                        borderBottom: "1px solid rgba(255, 255, 255, 0.04)",
                        maxWidth: column.maxWidth || "none",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                        fontFamily: "'Montserrat', sans-serif",
                      }}
                    >
                      <SafeCell column={column} row={row} />
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </TableContainer>

      {/* ── Pagination ──────────────────────────────────────────────────── */}
      <TablePagination
        rowsPerPageOptions={[5, 10, 25, 50]}
        component="div"
        count={safePagination.totalCount}
        rowsPerPage={safePagination.rowsPerPage}
        page={safePagination.page}
        onPageChange={safePagination.onPageChange}
        onRowsPerPageChange={safePagination.onRowsPerPageChange}
        labelRowsPerPage="Rows:"
        SelectProps={{
          MenuProps: {
            PaperProps: {
              sx: {
                bgcolor: "#001e08ff",
                border: "1px solid rgba(255, 255, 255, 0.1)",
                borderRadius: "8px",
                boxShadow: "0 4px 20px rgba(0,0,0,0.5)",
                "& .MuiMenuItem-root": {
                  fontSize: "0.75rem",
                  fontFamily: "'Montserrat', sans-serif",
                  color: "#FFFFFF",
                  minHeight: "32px",
                  py: "4px",
                  px: "12px",
                  "&:hover": {
                    bgcolor: "rgba(76,198,110,0.12)",
                    color: "#4CC66E",
                  },
                  "&.Mui-selected": {
                    bgcolor: "rgba(76,198,110,0.18)",
                    color: "#4CC66E",
                    fontWeight: 700,
                    "&:hover": { bgcolor: "rgba(76,198,110,0.25)" },
                  },
                },
              },
            },
          },
        }}
        sx={{
          borderTop: "1px solid rgba(255, 255, 255, 0.08)",
          bgcolor: "transparent",
          color: "#8B8D97",
          fontFamily: "'Montserrat', sans-serif",
          fontSize: "0.8rem",
          minHeight: 48,
          "& .MuiToolbar-root": {
            minHeight: "48px !important",
            px: { xs: 1, md: 2 },
            flexWrap: "wrap",
            justifyContent: "flex-end",
            gap: 0.5,
          },
          "& .MuiTablePagination-spacer": { display: "none" },
          "& .MuiTablePagination-selectLabel": {
            fontSize: "0.75rem",
            color: "#8B8D97",
            fontFamily: "'Montserrat', sans-serif",
            mb: 0,
            mt: 0,
          },
          "& .MuiTablePagination-displayedRows": {
            fontSize: "0.75rem",
            color: "#8B8D97",
            fontFamily: "'Montserrat', sans-serif",
            mb: 0,
            mt: 0,
          },
          "& .MuiSelect-select": {
            fontSize: "0.75rem",
            color: "#FFFFFF",
            fontFamily: "'Montserrat', sans-serif",
            py: "4px !important",
            pl: "0px !important",
            pr: "32px !important",
            borderRadius: "6px",
            border: "1px solid rgba(255, 255, 255, 0.1)",
            bgcolor: "rgba(255, 255, 255, 0.03)",
            minWidth: "48px !important",
            "&:focus": { bgcolor: "#111111" },
          },
          "& .MuiNativeSelect-select": {
            fontSize: "0.75rem",
            color: "#FFFFFF",
          },
          "& .MuiInputBase-root": {
            ml: 0.5,
            mr: 0.5,
            color: "#FFFFFF",
            "&::before, &::after": { display: "none" },
          },
          "& .MuiTablePagination-actions": {
            ml: 1,
            "& .MuiButtonBase-root": {
              color: "#8B8D97",
              padding: "4px",
              "&:not(.Mui-disabled):hover": {
                color: "#4CC66E",
                bgcolor: "rgba(76,198,110,0.08)",
              },
              "&.Mui-disabled": { color: "#333" },
            },
          },
        }}
      />

      {/* Internal Export Flow Components */}
      {onExport && (
        <>
          <Menu
            anchorEl={exportAnchorEl}
            open={Boolean(exportAnchorEl)}
            onClose={handleCloseExportMenu}
            PaperProps={{
              sx: {
                bgcolor: "#001e08ff",
                border: "1px solid rgba(255, 255, 255, 0.1)",
                borderRadius: "12px",
                boxShadow: "0 8px 32px rgba(0, 0, 0, 0.6)",
                mt: 1,
                "& .MuiMenuItem-root": {
                  fontSize: "0.8rem",
                  color: "#FFFFFF",
                  fontFamily: "'Montserrat', sans-serif",
                  py: 1.5,
                  px: 3,
                  "&:hover": {
                    bgcolor: alpha("#4CC66E", 0.1),
                    color: "#4CC66E"
                  }
                }
              }
            }}
          >
            <MenuItem onClick={() => handleSelectExportFormat("excel")}>
              Export as Excel (.xlsx)
            </MenuItem>
            <MenuItem onClick={() => handleSelectExportFormat("csv")}>
              Export as CSV (.csv)
            </MenuItem>
          </Menu>

          <DateRangeModal
            open={isDateModalOpen}
            onClose={() => setIsDateModalOpen(false)}
            onApply={handleApplyDateRange}
            loading={isExporting}
          />
        </>
      )}
    </Paper>
  );
};

export default DataTable;
